#include "GuiStyle.hpp"

#include <algorithm>
#include <cmath>
#include <imgui.h>
#include <imgui_impl_opengl3.h>
#include <implot.h>

// Generated by cmake/EmbedFile.cmake
extern const unsigned char caneo_font_ui[];
extern const unsigned int  caneo_font_ui_size;
extern const unsigned char caneo_font_mono[];
extern const unsigned int  caneo_font_mono_size;

namespace gui_style {

static ImFont* s_mono = nullptr;

ImFont* mono_font() { return s_mono; }

void apply(float scale, const std::string& theme, bool backend_ready)
{
    scale = std::clamp(scale, 0.5f, 4.0f);
    ImGuiIO& io = ImGui::GetIO();

    // ── fonts: rasterised at the target size so text stays sharp ──
    io.Fonts->Clear();
    ImFontConfig cfg;
    cfg.FontDataOwnedByAtlas = false;   // data lives in the binary
    cfg.OversampleH = 2;

    // Latin-1 plus Greek (Δ, µ in DBC units) and general punctuation (–, …, ‰).
    static ImVector<ImWchar> ranges;
    if (ranges.empty()) {
        ImFontGlyphRangesBuilder builder;
        builder.AddRanges(io.Fonts->GetGlyphRangesGreek());
        static const ImWchar extra[] = { 0x2000, 0x206F, 0x2190, 0x21FF, 0x2200, 0x22FF, 0 };
        builder.AddRanges(extra);
        builder.BuildRanges(&ranges);
    }
    io.Fonts->AddFontFromMemoryTTF(const_cast<unsigned char*>(caneo_font_ui),
                                   static_cast<int>(caneo_font_ui_size),
                                   std::round(16.0f * scale), &cfg, ranges.Data);
    s_mono = io.Fonts->AddFontFromMemoryTTF(const_cast<unsigned char*>(caneo_font_mono),
                                            static_cast<int>(caneo_font_mono_size),
                                            std::round(15.0f * scale), &cfg, ranges.Data);
    io.Fonts->Build();
    io.FontGlobalScale = 1.0f;
    if (backend_ready) {
        ImGui_ImplOpenGL3_DestroyFontsTexture();
        ImGui_ImplOpenGL3_CreateFontsTexture();
    }

    // ── style ──
    ImGuiStyle style;
    if (theme == "dark") {
        ImGui::StyleColorsDark(&style);
        ImPlot::StyleColorsDark();
    } else {
        ImGui::StyleColorsLight(&style);
        ImPlot::StyleColorsLight();
    }
    style.WindowRounding    = 4.0f;
    style.FrameRounding     = 3.0f;
    style.GrabRounding      = 3.0f;
    style.TabRounding       = 3.0f;
    style.PopupRounding     = 3.0f;
    style.ScrollbarRounding = 6.0f;
    style.FramePadding      = ImVec2(6.0f, 4.0f);
    style.ItemSpacing       = ImVec2(8.0f, 5.0f);
    style.WindowPadding     = ImVec2(8.0f, 8.0f);
    style.ScaleAllSizes(scale);
    ImGui::GetStyle() = style;

    ImPlotStyle& ps = ImPlot::GetStyle();
    ps.LineWeight     = 2.0f;
    ps.PlotPadding    = ImVec2(10 * scale, 10 * scale);
    ps.LabelPadding   = ImVec2(5 * scale, 2 * scale);
    ps.LegendPadding  = ImVec2(10 * scale, 10 * scale);
    ps.LegendInnerPadding = ImVec2(5 * scale, 5 * scale);
    ps.LegendSpacing  = ImVec2(5 * scale, 0);
    ps.MousePosPadding = ImVec2(10 * scale, 10 * scale);
    ps.MajorTickLen   = ImVec2(10 * scale, 10 * scale);
    ps.MinorTickLen   = ImVec2(5 * scale, 5 * scale);
}

} // namespace gui_style
